using System.ComponentModel;
using System.Net;
using System.Text.Json;
using System.Text.RegularExpressions;
using Microsoft.Extensions.AI;

namespace ResearchAgent.Tools;

/// <summary>
/// Provides web search capabilities for the research agent.
/// Uses DuckDuckGo's API for search and HttpClient for page fetching.
/// </summary>
public sealed class WebSearchTool
{
    private readonly HttpClient _httpClient;

    public WebSearchTool(HttpClient httpClient)
    {
        _httpClient = httpClient;
    }

    [Description("Searches the web for a query and returns a list of result titles, URLs, and snippets.")]
    public async Task<string> SearchWeb(
        [Description("The search query")] string query,
        [Description("Maximum number of results to return")] int maxResults = 5)
    {
        try
        {
            var encoded = Uri.EscapeDataString(query);
            var url = $"https://html.duckduckgo.com/html/?q={encoded}";

            using var request = new HttpRequestMessage(HttpMethod.Get, url);
            request.Headers.UserAgent.ParseAdd("ResearchAgent/1.0");

            var response = await _httpClient.SendAsync(request);
            response.EnsureSuccessStatusCode();
            var html = await response.Content.ReadAsStringAsync();

            var results = ParseSearchResults(html, maxResults);

            if (results.Count == 0)
            {
                return $"No results found for '{query}'.";
            }

            return JsonSerializer.Serialize(results, new JsonSerializerOptions { WriteIndented = true });
        }
        catch (Exception ex)
        {
            return $"Search failed: {ex.Message}. Try a different query or use FetchWebPage with a direct URL.";
        }
    }

    [Description("Fetches the text content of a web page given its URL. Use this to read full articles.")]
    public async Task<string> FetchWebPage(
        [Description("The URL of the page to fetch")] string url,
        [Description("Maximum characters to return")] int maxLength = 5000)
    {
        try
        {
            using var request = new HttpRequestMessage(HttpMethod.Get, url);
            request.Headers.UserAgent.ParseAdd("ResearchAgent/1.0");

            var response = await _httpClient.SendAsync(request);
            response.EnsureSuccessStatusCode();
            var html = await response.Content.ReadAsStringAsync();

            var text = StripHtml(html);

            if (text.Length > maxLength)
            {
                text = text[..maxLength] + "\n... [truncated]";
            }

            return string.IsNullOrWhiteSpace(text)
                ? "Page content could not be extracted."
                : text;
        }
        catch (Exception ex)
        {
            return $"Failed to fetch page: {ex.Message}";
        }
    }

    private static List<SearchResult> ParseSearchResults(string html, int maxResults)
    {
        var results = new List<SearchResult>();

        var linkPattern = new Regex(
            @"<a[^>]+class=""result__a""[^>]*href=""([^""]+)""[^>]*>(.*?)</a>",
            RegexOptions.Singleline);

        var snippetPattern = new Regex(
            @"<a[^>]+class=""result__snippet""[^>]*>(.*?)</a>",
            RegexOptions.Singleline);

        var links = linkPattern.Matches(html);
        var snippets = snippetPattern.Matches(html);

        for (int i = 0; i < Math.Min(links.Count, maxResults); i++)
        {
            var rawUrl = links[i].Groups[1].Value;
            var title = StripHtml(links[i].Groups[2].Value).Trim();
            var snippet = i < snippets.Count
                ? StripHtml(snippets[i].Groups[1].Value).Trim()
                : "";

            var decodedUrl = ExtractActualUrl(rawUrl);

            results.Add(new SearchResult(title, decodedUrl, snippet));
        }

        return results;
    }

    private static string ExtractActualUrl(string ddgUrl)
    {
        // DuckDuckGo wraps URLs in a redirect; extract the actual URL.
        var match = Regex.Match(ddgUrl, @"uddg=([^&]+)");
        if (match.Success)
        {
            return Uri.UnescapeDataString(match.Groups[1].Value);
        }

        return ddgUrl;
    }

    private static string StripHtml(string html)
    {
        var text = Regex.Replace(html, @"<script[^>]*>.*?</script>", " ", RegexOptions.Singleline);
        text = Regex.Replace(text, @"<style[^>]*>.*?</style>", " ", RegexOptions.Singleline);
        text = Regex.Replace(text, @"<[^>]+>", " ");
        text = WebUtility.HtmlDecode(text);
        text = Regex.Replace(text, @"\s+", " ");
        return text.Trim();
    }

    private sealed record SearchResult(string Title, string Url, string Snippet);
}

using System.ComponentModel;
using System.Text.Json;

namespace ResearchAgent.Tools;

/// <summary>
/// Provides note-taking capabilities for the research agent to organize findings.
/// </summary>
public sealed class NoteTool
{
    private readonly List<ResearchNote> _notes = [];

    [Description("Saves a research note with a title and content. Use this to record key findings from your research.")]
    public string SaveNote(
        [Description("A short descriptive title for the note")] string title,
        [Description("The content/body of the note")] string content,
        [Description("The source URL, if applicable")] string? sourceUrl = null)
    {
        var note = new ResearchNote(
            Id: _notes.Count + 1,
            Title: title,
            Content: content,
            SourceUrl: sourceUrl,
            Timestamp: DateTime.UtcNow);

        _notes.Add(note);
        return $"Note #{note.Id} saved: \"{title}\"";
    }

    [Description("Retrieves all saved research notes. Use this to review what you've found so far before writing a summary.")]
    public string GetAllNotes()
    {
        if (_notes.Count == 0)
        {
            return "No notes saved yet.";
        }

        return JsonSerializer.Serialize(_notes, new JsonSerializerOptions { WriteIndented = true });
    }

    [Description("Deletes a note by its ID.")]
    public string DeleteNote([Description("The ID of the note to delete")] int noteId)
    {
        var note = _notes.Find(n => n.Id == noteId);
        if (note is null)
        {
            return $"Note #{noteId} not found.";
        }

        _notes.Remove(note);
        return $"Note #{noteId} deleted.";
    }

    public IReadOnlyList<ResearchNote> Notes => _notes.AsReadOnly();

    public sealed record ResearchNote(
        int Id,
        string Title,
        string Content,
        string? SourceUrl,
        DateTime Timestamp);
}

