using System.ClientModel;
using Microsoft.Extensions.AI;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Hosting;
using Microsoft.Extensions.Logging;
using OpenAI;
using ResearchAgent.Tools;

var builder = Host.CreateApplicationBuilder(args);

// --- Service registration ---
builder.Services.AddHttpClient<WebSearchTool>();
builder.Services.AddSingleton<NoteTool>();

builder.Services.AddChatClient(chatBuilder =>
{
    var apiKey = builder.Configuration["AI:ApiKey"]
        ?? Environment.GetEnvironmentVariable("OPENAI_API_KEY")
        ?? throw new InvalidOperationException(
            "Set the API key via AI:ApiKey in config or the OPENAI_API_KEY environment variable.");

    var modelId = builder.Configuration["AI:ModelId"] ?? "gpt-4o-mini-2024-07-18";

    return chatBuilder
        .UseLogging()
        .Use(new OpenAIClient(new ApiKeyCredential(apiKey))
            .GetChatClient(modelId)
            .AsIChatClient());
});

builder.Logging.SetMinimumLevel(LogLevel.Warning);

var host = builder.Build();

// --- Resolve services ---
var chatClient = host.Services.GetRequiredService<IChatClient>();
var webSearch = host.Services.GetRequiredService<WebSearchTool>();
var noteTool = host.Services.GetRequiredService<NoteTool>();
var logger = host.Services.GetRequiredService<ILoggerFactory>().CreateLogger("ResearchAgent");

// --- Build tool list ---
var tools = new AIFunction[]
{
    AIFunctionFactory.Create(webSearch.SearchWeb, nameof(webSearch.SearchWeb)),
    AIFunctionFactory.Create(webSearch.FetchWebPage, nameof(webSearch.FetchWebPage)),
    AIFunctionFactory.Create(noteTool.SaveNote, nameof(noteTool.SaveNote)),
    AIFunctionFactory.Create(noteTool.GetAllNotes, nameof(noteTool.GetAllNotes)),
    AIFunctionFactory.Create(noteTool.DeleteNote, nameof(noteTool.DeleteNote)),
};

// --- Get research topic ---
Console.ForegroundColor = ConsoleColor.Cyan;
Console.WriteLine("╔══════════════════════════════════════╗");
Console.WriteLine("║       🔍 AI Research Agent           ║");
Console.WriteLine("╚══════════════════════════════════════╝");
Console.ResetColor();
Console.WriteLine();

string topic;
if (args.Length > 0)
{
    topic = string.Join(' ', args);
}
else
{
    Console.Write("Enter a research topic: ");
    topic = Console.ReadLine()?.Trim() ?? "";
}

if (string.IsNullOrWhiteSpace(topic))
{
    Console.Error.WriteLine("No topic provided. Exiting.");
    return 1;
}

Console.WriteLine();
Console.ForegroundColor = ConsoleColor.Yellow;
Console.WriteLine($"Researching: {topic}");
Console.ResetColor();
Console.WriteLine();

// --- Run the agent loop ---
var systemPrompt = """
    You are a research agent. Your goal is to thoroughly research a topic and produce a well-organized summary.

    Follow this workflow:
    1. Search the web for the topic using SearchWeb.
    2. Read 2-3 of the most relevant results using FetchWebPage.
    3. Save key findings as notes using SaveNote (include source URLs).
    4. After gathering enough information, retrieve all notes with GetAllNotes.
    5. Produce a final summary that synthesizes your notes into a coherent report.

    Your final response must be the summary. Include a "Sources" section at the end listing the URLs you used.
    Be factual and cite your sources. If you can't find reliable information, say so.
    """;

var chatOptions = new ChatOptions
{
    Temperature = 0f,
    MaxOutputTokens = 4096,
    Tools = [.. tools],
    ToolMode = ChatToolMode.Auto,
};

var messages = new List<ChatMessage>
{
    new(ChatRole.System, systemPrompt),
    new(ChatRole.User, $"Research the following topic and provide a comprehensive summary: {topic}"),
};

const int maxIterations = 15;
int iteration = 0;

while (iteration++ < maxIterations)
{
    var response = await chatClient.GetResponseAsync(messages, chatOptions);

    // Append all response messages to the conversation
    foreach (var msg in response.Messages)
    {
        messages.Add(msg);
    }

    // Check if the model made tool calls
    var toolCalls = response.Messages
        .SelectMany(m => m.Contents.OfType<FunctionCallContent>())
        .ToList();

    if (toolCalls.Count == 0)
    {
        // No tool calls — the agent has produced its final answer
        var finalText = response.Messages
            .Where(m => m.Role == ChatRole.Assistant)
            .SelectMany(m => m.Contents.OfType<TextContent>())
            .Select(t => t.Text)
            .LastOrDefault();

        if (!string.IsNullOrWhiteSpace(finalText))
        {
            Console.ForegroundColor = ConsoleColor.Green;
            Console.WriteLine("═══ Research Summary ═══");
            Console.ResetColor();
            Console.WriteLine(finalText);
        }

        break;
    }

    // Process each tool call
    foreach (var call in toolCalls)
    {
        Console.ForegroundColor = ConsoleColor.DarkGray;
        Console.WriteLine($"  → Calling {call.Name}...");
        Console.ResetColor();

        var tool = tools.FirstOrDefault(t => t.Name == call.Name);
        if (tool is null)
        {
            messages.Add(new ChatMessage(ChatRole.Tool,
                [new FunctionResultContent(call.CallId, call.Name, $"Unknown tool: {call.Name}")]));
            continue;
        }

        try
        {
            var result = await tool.InvokeAsync(call.Arguments);
            var resultText = result?.ToString() ?? "";

            logger.LogDebug("Tool {Name} returned {Length} chars", call.Name, resultText.Length);

            messages.Add(new ChatMessage(ChatRole.Tool,
                [new FunctionResultContent(call.CallId, call.Name, resultText)]));
        }
        catch (Exception ex)
        {
            messages.Add(new ChatMessage(ChatRole.Tool,
                [new FunctionResultContent(call.CallId, call.Name, $"Error: {ex.Message}")]));
        }
    }
}

if (iteration > maxIterations)
{
    Console.ForegroundColor = ConsoleColor.Red;
    Console.WriteLine("Agent reached maximum iterations without producing a final summary.");
    Console.ResetColor();
}

// --- Print collected notes ---
if (noteTool.Notes.Count > 0)
{
    Console.WriteLine();
    Console.ForegroundColor = ConsoleColor.DarkCyan;
    Console.WriteLine($"({noteTool.Notes.Count} research note(s) were collected during this session)");
    Console.ResetColor();
}

return 0;

