1. using System.ClientModel;
2. using Microsoft.Extensions.AI;
3. using Microsoft.Extensions.DependencyInjection;
4. using Microsoft.Extensions.Hosting;
5. using Microsoft.Extensions.Logging;
6. using OpenAI;
7. using ResearchAgent.Tools;
8. 
9. var builder = Host.CreateApplicationBuilder(args);
10. 
11. // --- Service registration ---
12. builder.Services.AddHttpClient<WebSearchTool>();
13. builder.Services.AddSingleton<NoteTool>();
14. 
15. var apiKey = builder.Configuration["AI:ApiKey"]
16.     ?? Environment.GetEnvironmentVariable("OPENAI_API_KEY")
17.     ?? throw new InvalidOperationException(
18.         "Set the API key via AI:ApiKey in config or the OPENAI_API_KEY environment variable.");
19. 
20. var modelId = builder.Configuration["AI:ModelId"] ?? "gpt-4o-mini-2024-07-18";
21. 
22. builder.Services.AddChatClient(sp =>
23.         new OpenAIClient(new ApiKeyCredential(apiKey))
24.             .GetChatClient(modelId)
25.             .AsIChatClient())
26.     .UseLogging();
27. 
28. builder.Logging.SetMinimumLevel(LogLevel.Warning);
29. 
30. var host = builder.Build();
31. 
32. // --- Resolve services ---
33. var chatClient = host.Services.GetRequiredService<IChatClient>();
34. var webSearch = host.Services.GetRequiredService<WebSearchTool>();
35. var noteTool = host.Services.GetRequiredService<NoteTool>();
36. var logger = host.Services.GetRequiredService<ILoggerFactory>().CreateLogger("ResearchAgent");
37. 
38. // --- Build tool list ---
39. var tools = new AIFunction[]
40. {
41.     AIFunctionFactory.Create(webSearch.SearchWeb, nameof(webSearch.SearchWeb)),
42.     AIFunctionFactory.Create(webSearch.FetchWebPage, nameof(webSearch.FetchWebPage)),
43.     AIFunctionFactory.Create(noteTool.SaveNote, nameof(noteTool.SaveNote)),
44.     AIFunctionFactory.Create(noteTool.GetAllNotes, nameof(noteTool.GetAllNotes)),
45.     AIFunctionFactory.Create(noteTool.DeleteNote, nameof(noteTool.DeleteNote)),
46. };
47. 
48. // --- Get research topic ---
49. Console.ForegroundColor = ConsoleColor.Cyan;
50. Console.WriteLine("╔══════════════════════════════════════╗");
51. Console.WriteLine("║       🔍 AI Research Agent           ║");
52. Console.WriteLine("╚══════════════════════════════════════╝");
53. Console.ResetColor();
54. Console.WriteLine();
55. 
56. string topic;
57. if (args.Length > 0)
58. {
59.     topic = string.Join(' ', args);
60. }
61. else
62. {
63.     Console.Write("Enter a research topic: ");
64.     topic = Console.ReadLine()?.Trim() ?? "";
65. }
66. 
67. if (string.IsNullOrWhiteSpace(topic))
68. {
69.     Console.Error.WriteLine("No topic provided. Exiting.");
70.     return 1;
71. }
72. 
73. Console.WriteLine();
74. Console.ForegroundColor = ConsoleColor.Yellow;
75. Console.WriteLine($"Researching: {topic}");
76. Console.ResetColor();
77. Console.WriteLine();
78. 
79. // --- Run the agent loop ---
80. var systemPrompt = """
81.     You are a research agent. Your goal is to thoroughly research a topic and produce a well-organized summary.
82. 
83.     Follow this workflow:
84.     1. Search the web for the topic using SearchWeb.
85.     2. Read 2-3 of the most relevant results using FetchWebPage.
86.     3. Save key findings as notes using SaveNote (include source URLs).
87.     4. After gathering enough information, retrieve all notes with GetAllNotes.
88.     5. Produce a final summary that synthesizes your notes into a coherent report.
89. 
90.     Your final response must be the summary. Include a "Sources" section at the end listing the URLs you used.
91.     Be factual and cite your sources. If you can't find reliable information, say so.
92.     """;
93. 
94. var chatOptions = new ChatOptions
95. {
96.     Temperature = 0f,
97.     MaxOutputTokens = 4096,
98.     Tools = [.. tools],
99.     ToolMode = ChatToolMode.Auto,
100. };
101. 
102. var messages = new List<ChatMessage>
103. {
104.     new(ChatRole.System, systemPrompt),
105.     new(ChatRole.User, $"Research the following topic and provide a comprehensive summary: {topic}"),
106. };
107. 
108. const int maxIterations = 15;
109. int iteration = 0;
110. 
